code='''from collections import Counter, deque

def _rectangle_area(grid, r, c, color):
    h, w = len(grid), len(grid[0])
    best = 1
    for top in range(r + 1):
        for bottom in range(r, h):
            for left in range(c + 1):
                for right in range(c, w):
                    area = (bottom - top + 1) * (right - left + 1)
                    if area <= best:
                        continue
                    if all((y == r and x == c) or grid[y][x] == color
                           for y in range(top, bottom + 1)
                           for x in range(left, right + 1)):
                        best = area
    return best

def transform(grid):
    h, w = len(grid), len(grid[0])
    color_counts = Counter(value for row in grid for value in row)
    background = max(color_counts, key=color_counts.get)
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(component) != 1:
                continue
            neighbors = [grid[ny][nx] for ny, nx in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                         if 0 <= ny < h and 0 <= nx < w]
            counts = Counter(neighbors)
            best_count = max(counts.values())
            candidates = [v for v, n in counts.items() if n == best_count]
            if len(candidates) == 1:
                out[r][c] = candidates[0]
                continue
            # Prefer a color that restores an otherwise uniform row or column.
            line_candidates = [v for v in candidates
                               if all(grid[r][x] == v for x in range(w) if x != c)
                               or all(grid[y][c] == v for y in range(h) if y != r)]
            if line_candidates:
                out[r][c] = max(line_candidates, key=lambda v: color_counts[v])
                continue
            # Otherwise restore a bounded rectangular region rather than the background.
            object_candidates = [v for v in candidates if v != background]
            if object_candidates:
                out[r][c] = max(object_candidates, key=lambda v: _rectangle_area(grid, r, c, v))
            else:
                out[r][c] = max(candidates, key=lambda v: color_counts[v])
    return out
'''
